import { parse } from '@babel/parser'
import { prepareRuntimeSource } from '@hrbr/runtime-planner/source-prep'

export const INSPECT_RESULT_KIND = 'harbor.inspect_result'

export const inspectRootGlobalNames = ['hrbr', 'defineJob', 'deployApp'] as const

export const legacyInspectDomainNames = [
  'auth',
  'workspace',
  'sources',
  'plugins',
  'tools',
  'jobs',
  'apps',
  'harbor',
] as const

export type InspectEvalResult = {
  readonly ok: boolean
  readonly result: unknown
  readonly logs: readonly string[]
  readonly error?: string | undefined
}

export interface BuildInspectRuntimeSourceOptions {
  readonly domainKeys: readonly string[]
  readonly hostCallSetup: readonly string[]
  readonly resultEnvelope?: boolean | undefined
  readonly resultKind?: string | undefined
  readonly deployAppRuntime?: string | null | undefined
  readonly clearGlobalHostCall?: boolean | undefined
}

export interface BuildQuickJsInspectSourceOptions {
  readonly domainKeys: readonly string[]
  readonly deployAppRuntime?: string | null | undefined
}

export interface BuildDispatchInspectWorkerSourceOptions {
  readonly domainKeys: readonly string[]
  readonly resultKind?: string | undefined
  readonly deployAppRuntime?: string | null | undefined
  readonly hostDispatchExpression?: string | undefined
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

const isNode = (value: unknown): value is Record<string, unknown> =>
  Boolean(
    value && typeof value === 'object' && typeof (value as { type?: unknown }).type === 'string'
  )

const walk = (node: unknown, visit: (node: Record<string, unknown>) => void): void => {
  if (!isNode(node)) return
  visit(node)
  for (const [key, value] of Object.entries(node)) {
    if (key === 'loc' || key === 'start' || key === 'end' || key === 'extra') continue
    if (Array.isArray(value)) {
      for (const child of value) walk(child, visit)
    } else {
      walk(value, visit)
    }
  }
}

const collectBindingNames = (node: unknown, names: Set<string>): void => {
  if (!isNode(node)) return
  if (node.type === 'Identifier' && typeof node.name === 'string') {
    names.add(node.name)
    return
  }
  if (node.type === 'RestElement') {
    collectBindingNames(node.argument, names)
    return
  }
  if (node.type === 'AssignmentPattern') {
    collectBindingNames(node.left, names)
    return
  }
  if (node.type === 'TSParameterProperty') {
    collectBindingNames(node.parameter, names)
    return
  }
  if (node.type === 'ObjectPattern') {
    for (const property of Array.isArray(node.properties) ? node.properties : []) {
      if (!isNode(property)) continue
      if (property.type === 'RestElement') collectBindingNames(property.argument, names)
      if (property.type === 'ObjectProperty') collectBindingNames(property.value, names)
    }
    return
  }
  if (node.type === 'ArrayPattern') {
    for (const element of Array.isArray(node.elements) ? node.elements : []) {
      collectBindingNames(element, names)
    }
  }
}

export function inspectGlobalShadowingError(code: string): string | undefined {
  let ast: unknown
  try {
    ast = parse(code, {
      sourceType: 'unambiguous',
      allowReturnOutsideFunction: true,
      plugins: ['typescript', 'jsx'],
      errorRecovery: false,
    })
  } catch {
    return undefined
  }

  const declared = new Set<string>()
  walk(ast, (node) => {
    if (node.type === 'VariableDeclarator') collectBindingNames(node.id, declared)
    if (node.type === 'FunctionDeclaration' || node.type === 'ClassDeclaration') {
      collectBindingNames(node.id, declared)
    }
    if (
      node.type === 'FunctionDeclaration' ||
      node.type === 'FunctionExpression' ||
      node.type === 'ArrowFunctionExpression' ||
      node.type === 'ObjectMethod' ||
      node.type === 'ClassMethod' ||
      node.type === 'ClassPrivateMethod'
    ) {
      for (const param of Array.isArray(node.params) ? node.params : []) {
        collectBindingNames(param, declared)
      }
    }
    if (
      node.type === 'ImportSpecifier' ||
      node.type === 'ImportDefaultSpecifier' ||
      node.type === 'ImportNamespaceSpecifier'
    ) {
      collectBindingNames(node.local, declared)
    }
    if (node.type === 'CatchClause') collectBindingNames(node.param, declared)
  })

  const reserved = inspectRootGlobalNames.filter((name) => declared.has(name))
  if (reserved.length === 0) return undefined
  const names = reserved.map((name) => JSON.stringify(name)).join(', ')
  return (
    'Inspect code must not declare local bindings named ' +
    names +
    ' because hrbr is the single Harbor inspect global. Rename the local binding, then call Harbor domains through hrbr.<domain>; for example: const sources = await hrbr.sources.list().'
  )
}

export function applyInspectErrorHint(
  _code: string,
  error: string | undefined
): string | undefined {
  if (!error) return undefined
  if (error.includes("'sand' is not defined") || error.includes('sand is not defined')) {
    return (
      error +
      ' Hint: sand is not available in Harbor inspect. inspect exposes one control-plane global: hrbr. Use Harbor cloud sources through exec.'
    )
  }
  for (const name of legacyInspectDomainNames) {
    const isShadowingError =
      error.includes(name + ' is not defined') ||
      error.includes("'" + name + "' is not defined") ||
      error.includes('"' + name + '" is not defined') ||
      error.includes(name + ' is not initialized') ||
      error.includes("Cannot access '" + name + "' before initialization") ||
      error.includes('Cannot access "' + name + '" before initialization')
    if (isShadowingError) {
      if (name === 'plugins') {
        return error + ' Hint: Use hrbr.sources.*, not hrbr.plugins.*, in Harbor inspect.'
      }
      const domain = name === 'harbor' ? 'hrbr' : 'hrbr.' + name
      return (
        error +
        ' Hint: inspect exposes one control-plane global named hrbr. Use ' +
        domain +
        ' instead.'
      )
    }
  }
  return error
}

export function wrapInspectUserCode(code: string): string {
  const transformed = prepareRuntimeSource(code, 'inspect').code.trim()

  if (/\bdeployApp\s*\(/.test(transformed)) {
    return '(async () => {\n' + transformed + '\nreturn await globalThis.__deployAppPromise;\n})()'
  }
  if (/\bdefineJob\s*\(/.test(transformed)) {
    return '(async () => {\n' + transformed + '\nreturn await globalThis.__defineJobPromise;\n})()'
  }
  if (/\breturn\b/.test(transformed) || /\bawait\b/.test(transformed)) {
    return '(async () => {\n' + transformed + '\n})()'
  }

  return '(async () => (' + transformed + '))()'
}

const deployAppRuntimeLine = (runtime: string | null | undefined): string[] =>
  runtime == null ? [] : ['    runtime: ' + JSON.stringify(runtime) + ',']

const schemaAndAuthoringLines = (deployAppRuntime: string | null | undefined): string[] => [
  'function __schemaShortcut(value, path) {',
  '  if (typeof value === "string") {',
  '    const optional = value.endsWith("?");',
  '    const type = optional ? value.slice(0, -1) : value;',
  '    if (!["string", "number", "boolean", "unknown"].includes(type)) throw new Error(path + " uses unsupported schema shortcut " + value);',
  '    return { optional, schema: type === "unknown" ? {} : { type } };',
  '  }',
  '  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error(path + " must be a schema object or shortcut string");',
  '  if (typeof value.type === "string" || Array.isArray(value.type)) return { optional: false, schema: value };',
  '  const properties = {}; const required = [];',
  '  for (const [key, child] of Object.entries(value)) { const out = __schemaShortcut(child, path + "." + key); properties[key] = out.schema; if (!out.optional) required.push(key); }',
  '  return { optional: false, schema: { type: "object", properties, required, additionalProperties: false } };',
  '}',
  'function __canonicalJobName(raw) {',
  '  const value = String(raw || "").trim();',
  '  if (/^[a-z][a-z0-9-]{0,127}$/.test(value)) return value;',
  '  if (!/^[A-Za-z][A-Za-z0-9]{0,127}$/.test(value)) throw new Error("defineJob.name must be kebab-case or camelCase");',
  '  return value.replace(/([a-z0-9])([A-Z])/g, "$1-$2").replace(/([A-Z])([A-Z][a-z])/g, "$1-$2").toLowerCase();',
  '}',
  'function __canonicalAppName(raw) {',
  '  const value = String(raw || "").trim();',
  '  if (/^[a-z][a-z0-9-]{0,127}$/.test(value)) return value;',
  '  if (!/^[A-Za-z][A-Za-z0-9]{0,127}$/.test(value)) throw new Error("deployApp.id must be kebab-case or camelCase");',
  '  return value.replace(/([a-z0-9])([A-Z])/g, "$1-$2").replace(/([A-Z])([A-Z][a-z])/g, "$1-$2").toLowerCase();',
  '}',
  'function __inferJobCapabilities(source) {',
  '  const caps = new Set();',
  '  if (/\\bhrbr\\s*\\.\\s*storage\\b|\\borbit\\s*\\.\\s*storage\\b/.test(source)) caps.add("storage");',
  '  if (/\\bhrbr\\s*\\.\\s*cache\\b|\\borbit\\s*\\.\\s*cache\\b/.test(source)) caps.add("memory");',
  '  if (/\\bhrbr\\s*\\.\\s*db\\b|\\borbit\\s*\\.\\s*db\\b/.test(source)) caps.add("data");',
  '  if (/\\bhrbr\\s*\\.\\s*ai\\b|\\borbit\\s*\\.\\s*ai\\b/.test(source)) caps.add("ai");',
  '  if (/\\bhrbr\\s*\\.\\s*tools\\b|\\bplugins\\s*\\.\\s*call\\b/.test(source)) caps.add("plugins");',
  '  return Array.from(caps);',
  '}',
  'function defineJob(definition) {',
  '  if (!definition || typeof definition !== "object") throw new Error("defineJob expects an object");',
  '  if (typeof definition.run !== "function") throw new Error("defineJob.run must be a function");',
  '  if (!definition.input) throw new Error("defineJob.input is required");',
  '  const body = {',
  '    name: __canonicalJobName(definition.name),',
  '    description: definition.description,',
  '    input_schema: __schemaShortcut(definition.input, "defineJob.input").schema,',
  '    output_schema: definition.output ? __schemaShortcut(definition.output, "defineJob.output").schema : undefined,',
  '    capabilities: __inferJobCapabilities(__inspectSource),',
  '    tags: definition.tags,',
  '    timeout_ms: definition.timeout_ms,',
  '    retry: definition.retry,',
  '    retention: definition.retention,',
  '    code: __inspectSource,',
  '    runtime: "define_job",',
  '  };',
  '  globalThis.__defineJobPromise = __hostCall(["jobs", "publish"], [body]);',
  '  return definition;',
  '}',
  'function __routeDefaults(method) {',
  '  return { input: ["GET", "DELETE", "OPTIONS"].includes(method) ? "none" : "json", output: method === "GET" ? "html" : "json" };',
  '}',
  'function __normalizeAppRoutes(definition, defaultAuth) {',
  '  if (!definition.routes || typeof definition.routes !== "object" || Array.isArray(definition.routes)) throw new Error("deployApp.routes must be an object keyed by method/path");',
  '  const routes = []; let hasHandlers = false;',
  '  for (const [key, value] of Object.entries(definition.routes)) {',
  '    if (!value || typeof value !== "object") throw new Error("deployApp.routes[" + key + "] must be an object");',
  '    const m = /^(GET|POST|PUT|PATCH|DELETE|OPTIONS)\\s+(\\/.*)$/.exec(key);',
  '    const method = String(value.method || (m && m[1]) || "").toUpperCase();',
  '    const path = String(value.path || (m && m[2]) || "");',
  '    if (!method || !path.startsWith("/")) throw new Error("deployApp route keys must look like GET /path");',
  '    const d = __routeDefaults(method);',
  '    const route = { method, path, auth: value.auth || defaultAuth, input: value.input || d.input, output: value.output || d.output };',
  '    if (value.id) route.id = value.id;',
  '    if (value.title) route.title = value.title;',
  '    if (value.tags) route.tags = value.tags;',
  '    if (value.rate_limit) route.rate_limit = value.rate_limit;',
  '    if (typeof value.run === "function") {',
  '      if (value.job || value.staticHtml || value.static_html) throw new Error("deployApp route " + key + " cannot combine run with job/staticHtml");',
  '      hasHandlers = true;',
  '    } else if (value.job) {',
  '      route.job = value.job;',
  '    } else if (value.staticHtml !== undefined || value.static_html !== undefined) {',
  '      route.static_html = value.staticHtml !== undefined ? value.staticHtml : value.static_html;',
  '    } else {',
  '      throw new Error("deployApp route " + key + " must declare run, job, or staticHtml");',
  '    }',
  '    routes.push(route);',
  '  }',
  '  if (routes.length === 0) throw new Error("deployApp.routes must contain at least one route");',
  '  return { routes, hasHandlers };',
  '}',
  'function __functionExpressionSource(fn) {',
  '  let source = fn.toString();',
  '  if (/^async\\s+[A-Za-z_$][\\w$]*\\s*\\(/.test(source)) source = source.replace(/^async\\s+[A-Za-z_$][\\w$]*\\s*\\(/, "async function(");',
  '  else if (/^[A-Za-z_$][\\w$]*\\s*\\(/.test(source)) source = source.replace(/^[A-Za-z_$][\\w$]*\\s*\\(/, "function(");',
  '  return source;',
  '}',
  'function __appRouteSource(route) {',
  '  const entries = [];',
  '  for (const [key, value] of Object.entries(route)) {',
  '    if (key === "run" && typeof value === "function") entries.push(JSON.stringify(key) + ": " + __functionExpressionSource(value));',
  '    else if (typeof value === "function") throw new Error("deployApp routes only support functions in the run field");',
  '    else if (value !== undefined) entries.push(JSON.stringify(key) + ": " + JSON.stringify(value));',
  '  }',
  '  return "{" + entries.join(",") + "}";',
  '}',
  'function __buildDeployAppCode(definition, name, routes, jobs, hasHandlers) {',
  '  if (!hasHandlers) return "export default defineOrbitApp(" + JSON.stringify({ name, description: definition.description || definition.title, jobs, routes, theme: definition.theme }) + ");";',
  '  const routesSource = "{" + Object.entries(definition.routes).map(([key, value]) => JSON.stringify(key) + ": " + __appRouteSource(value)).join(",") + "}";',
  '  return [',
  '    "const __hrbrDeployAppDefinition = { routes: " + routesSource + " };",',
  '    "export default defineOrbitApp({",',
  '    "  name: " + JSON.stringify(name) + ",",',
  '    definition.description || definition.title ? "  description: " + JSON.stringify(definition.description || definition.title) + "," : "",',
  '    "  jobs: " + JSON.stringify(jobs) + ",",',
  '    "  routes: " + JSON.stringify(routes) + ",",',
  '    "  async fetch(request, env, ctx) {",',
  '    "    void hrbr.cache;",',
  '    "    const url = new URL(request.url);",',
  '    "    const key = request.method + \\\" \\\" + (url.pathname || \\\"/\\\");",',
  '    "    const route = __hrbrDeployAppDefinition.routes[key];",',
  '    "    if (!route || typeof route.run !== \\\"function\\\") return new Response(\\\"Not found\\\", { status: 404 });",',
  '    "    return await route.run(request, env, ctx);",',
  '    "  }",',
  '    "});",',
  '  ].filter(Boolean).join("\\n");',
  '}',
  'function deployApp(definition) {',
  '  if (!definition || typeof definition !== "object") throw new Error("deployApp expects an object");',
  '  const name = __canonicalAppName(definition.id || definition.name);',
  '  const defaultAuth = definition.access || "workspace_member";',
  '  if (!["public", "workspace_member"].includes(defaultAuth)) throw new Error("deployApp.access must be public or workspace_member");',
  '  const jobs = definition.jobs || {};',
  '  const normalized = __normalizeAppRoutes(definition, defaultAuth);',
  '  const body = {',
  '    name,',
  '    description: definition.description || definition.title,',
  '    code: __buildDeployAppCode(definition, name, normalized.routes, jobs, normalized.hasHandlers),',
  ...deployAppRuntimeLine(deployAppRuntime),
  '    routes: normalized.routes,',
  '    jobs,',
  '    theme: definition.theme,',
  '    allowed_origins: definition.allowed_origins || definition.allowedOrigins,',
  '    idempotency_key: definition.idempotency_key || definition.idempotencyKey,',
  '  };',
  '  globalThis.__deployAppPromise = __hostCall(["apps", "publish"], [body]);',
  '  return definition;',
  '}',
]

export function buildInspectRuntimeSource(
  code: string,
  options: BuildInspectRuntimeSourceOptions
): string {
  const resultKind = options.resultKind ?? INSPECT_RESULT_KIND
  const lines = [
    ...options.hostCallSetup,
    'const __inspectSource = ' + JSON.stringify(code) + ';',
    'const __inspectDomainKeys = ' + JSON.stringify(options.domainKeys) + ';',
    'const __hostFunction = (path) => Object.freeze(function(...args) { return __hostCall(path, args); });',
    'function __freezeInspectSurface(value) {',
    '  if (!value || typeof value !== "object" || Object.isFrozen(value)) return value;',
    '  for (const child of Object.values(value)) __freezeInspectSurface(child);',
    '  return Object.freeze(value);',
    '}',
    'function __buildInspectSurface(keys) {',
    '  const root = Object.create(null);',
    '  for (const key of keys) {',
    '    const parts = key.split(".");',
    '    let cursor = root;',
    '    for (let index = 0; index < parts.length - 1; index++) {',
    '      const part = parts[index];',
    '      if (!cursor[part]) cursor[part] = Object.create(null);',
    '      cursor = cursor[part];',
    '    }',
    '    cursor[parts[parts.length - 1]] = __hostFunction(parts);',
    '  }',
    '  return __freezeInspectSurface(root);',
    '}',
    ...(options.resultEnvelope
      ? [
          'const console = {',
          '  log: (...args) => __inspectLogs.push(args.map(__inspectLogString).join(" ")),',
          '  info: (...args) => __inspectLogs.push(args.map(__inspectLogString).join(" ")),',
          '  warn: (...args) => __inspectLogs.push(args.map(__inspectLogString).join(" ")),',
          '  error: (...args) => __inspectLogs.push(args.map(__inspectLogString).join(" ")),',
          '};',
        ]
      : [
          'const console = {',
          '  log: (...args) => globalThis.__log(args),',
          '  info: (...args) => globalThis.__log(args),',
          '  warn: (...args) => globalThis.__log(args),',
          '  error: (...args) => globalThis.__log(args),',
          '};',
        ]),
    ...schemaAndAuthoringLines(options.deployAppRuntime),
    ...(options.resultEnvelope
      ? [
          'function __inspectJsonValue(value) {',
          '  const json = JSON.stringify(value, (_key, inner) => typeof inner === "bigint" ? inner.toString() : inner);',
          '  return json === undefined ? null : JSON.parse(json);',
          '}',
        ]
      : []),
    'const hrbr = __buildInspectSurface(__inspectDomainKeys);',
    'const fetch = undefined;',
    'const XMLHttpRequest = undefined;',
    'const WebSocket = undefined;',
    'globalThis.hrbr = hrbr;',
    'globalThis.defineJob = defineJob;',
    'globalThis.deployApp = deployApp;',
    'globalThis.fetch = undefined;',
    'globalThis.XMLHttpRequest = undefined;',
    'globalThis.WebSocket = undefined;',
    'globalThis.console = console;',
    ...(options.clearGlobalHostCall ? ['globalThis.__hostCall = undefined;'] : []),
    'globalThis.__userPromise = ' + wrapInspectUserCode(code) + ';',
    ...(options.resultEnvelope
      ? [
          'try {',
          '  const __inspectResult = await globalThis.__userPromise;',
          '  return { kind: ' +
            JSON.stringify(resultKind) +
            ', ok: true, result: __inspectJsonValue(__inspectResult), logs: __inspectLogs };',
          '} catch (__inspectError) {',
          '  const __inspectErrorText = __inspectError && __inspectError.message ? (__inspectError.name ? __inspectError.name + ": " + __inspectError.message : __inspectError.message) : String(__inspectError);',
          '  return { kind: ' +
            JSON.stringify(resultKind) +
            ', ok: false, result: null, error: __inspectErrorText, logs: __inspectLogs };',
          '}',
        ]
      : []),
  ]
  return lines.join('\n')
}

export function buildQuickJsInspectSource(
  code: string,
  options: BuildQuickJsInspectSourceOptions
): string {
  return buildInspectRuntimeSource(code, {
    domainKeys: options.domainKeys,
    hostCallSetup: ['const __hostCall = globalThis.__hostCall;'],
    deployAppRuntime: options.deployAppRuntime === undefined ? 'classic' : options.deployAppRuntime,
    clearGlobalHostCall: true,
  })
}

export function buildDispatchInspectWorkerSource(
  code: string,
  options: BuildDispatchInspectWorkerSourceOptions
): string {
  return buildInspectRuntimeSource(code, {
    domainKeys: options.domainKeys,
    hostCallSetup: [
      'const __inspectLogs = [];',
      'function __inspectLogString(value) { return typeof value === "string" ? value : JSON.stringify(value); }',
      'const __hostCall = (path, args) => ' +
        (options.hostDispatchExpression ??
          '__hrbr_env.HOST.dispatch({ inspect: { path, args } })') +
        ';',
    ],
    resultEnvelope: true,
    resultKind: options.resultKind,
    deployAppRuntime: options.deployAppRuntime,
  })
}

export function normalizeInspectWorkerResult(
  code: string,
  timeoutMs: number,
  workerResult: { result: unknown; error?: string | undefined; logs?: string[] | undefined },
  resultKind = INSPECT_RESULT_KIND
): InspectEvalResult {
  if (workerResult.error) {
    const rawError =
      workerResult.error === 'Execution timed out'
        ? 'inspect timed out after ' + timeoutMs + 'ms'
        : workerResult.error
    return {
      ok: false,
      result: null,
      logs: workerResult.logs ?? [],
      error: applyInspectErrorHint(code, rawError),
    }
  }
  const result = workerResult.result
  if (isRecord(result) && result.kind === resultKind) {
    const logs = Array.isArray(result.logs) ? result.logs.map(String) : []
    const nestedResult = isRecord(result.result) ? result.result : null
    const ok = result.ok === true
    const error = firstString(
      result.error,
      result.failure,
      result.message,
      result.inspect_error,
      result.error_message,
      result.result,
      nestedResult?.inspect_error,
      nestedResult?.failure,
      nestedResult?.error,
      nestedResult?.message,
      nestedResult?.error_message
    )
    return {
      ok,
      result: ok
        ? Object.prototype.hasOwnProperty.call(result, 'result')
          ? result.result
          : null
        : null,
      logs,
      ...(ok ? {} : { error: applyInspectErrorHint(code, error ?? 'Unknown inspect error') }),
    }
  }
  return { ok: true, result, logs: workerResult.logs ?? [] }
}

function firstString(...values: readonly unknown[]): string | undefined {
  for (const value of values) {
    if (typeof value === 'string' && value.length > 0) return value
  }
  return undefined
}
